// Supabase Auth + PostgREST. Only a publishable key is shipped to the client.
const sb=window.SUPABASE_CONFIG;
let session=JSON.parse(sessionStorage.getItem('sb-session')||'null'),loadingCloud=false;
const statusNames={aguardando:'Aguardando',processando:'Processando',concluida:'Concluída',nao_localizado:'Não localizado',erro:'Erro',revisao:'Revisão'};
const demoRender=render,demoAdd=add;
render=function(){demoRender();if(cfg.mode==='supabase'){$('.modeNotice').textContent='Supabase · Dados por usuário. As consultas aguardam o robô da VPS; não há valores simulados neste modo.';$('#clear').disabled=true;$('#demo').disabled=true}else{$('#clear').disabled=false;$('#demo').disabled=false}$('#authState').textContent=session?'Conectado: '+session.user.email:'Entre com um usuário do projeto Supabase.'};
async function refreshSession(){if(!session)throw Error('Entre na sua conta em Configurações.');if(Date.now()/1000<(session.expires_at||0)-60)return;const res=await fetch(sb.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:sb.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});const data=await res.json();if(!res.ok){session=null;sessionStorage.removeItem('sb-session');render();throw Error('Sessão expirada. Entre novamente.')}session={...data,expires_at:Math.floor(Date.now()/1000)+data.expires_in};sessionStorage.setItem('sb-session',JSON.stringify(session))}
async function sbRequest(path,options={}){await refreshSession();const res=await fetch(sb.url+path,{...options,headers:{apikey:sb.key,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(20000)});const text=await res.text(),data=text?JSON.parse(text):null;if(!res.ok)throw Error(data?.message||data?.msg||'Falha na conexão com Supabase');return data}
async function loadCloud(){if(cfg.mode!=='supabase'||!session||loadingCloud)return;loadingCloud=true;try{const data=await sbRequest('/rest/v1/consulta_jobs?select=*&order=created_at.desc&limit=1000');records=data.map(r=>({...r,date:r.consultado_em||r.created_at,status:statusNames[r.status]||r.status,saldo:r.saldo_liquidacao==null?null:Number(r.saldo_liquidacao),parcelas:r.total_parcelas,source:'Supabase',mode:'supabase'}));render()}catch(e){toast(e.message)}finally{loadingCloud=false}}
add=async function(items){if(cfg.mode!=='supabase')return demoAdd(items);try{await refreshSession();const batches=await sbRequest('/rest/v1/consulta_lotes',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({nome:items.length===1?'Consulta individual':'Importação CSV · '+items.length+' clientes'})});await sbRequest('/rest/v1/consulta_jobs',{method:'POST',body:JSON.stringify(items.map(r=>({nome:r.nome,cpf:r.cpf,telefone:r.telefone,lote_id:batches[0].id,user_id:session.user.id})))});toast(items.length+' consulta(s) salva(s) na fila do Supabase.');await loadCloud()}catch(e){toast(e.message)}};
$('#login').onsubmit=async e=>{e.preventDefault();try{const res=await fetch(sb.url+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:sb.key,'Content-Type':'application/json'},body:JSON.stringify({email:$('#email').value.trim(),password:$('#password').value})});const data=await res.json();if(!res.ok)throw Error(data.msg||data.error_description||'Não foi possível entrar');session={...data,expires_at:Math.floor(Date.now()/1000)+data.expires_in};sessionStorage.setItem('sb-session',JSON.stringify(session));$('#password').value='';records=[];render();await loadCloud();toast('Acesso realizado.')}catch(e){toast(e.message)}};
$('#logout').onclick=async()=>{try{if(session)await sbRequest('/auth/v1/logout',{method:'POST'})}catch{}session=null;sessionStorage.removeItem('sb-session');records=cfg.mode==='demo'?JSON.parse(localStorage.getItem('consultas-v1')||'[]'):[];render()};
$('#config').onsubmit=e=>{e.preventDefault();cfg={mode:$('#mode').value,url:''};localStorage.setItem('config-v1',JSON.stringify(cfg));records=cfg.mode==='demo'?JSON.parse(localStorage.getItem('consultas-v1')||'[]'):[];render();loadCloud();toast('Modo salvo.')};
const oldRowClick=$('#rows').onclick;$('#rows').onclick=e=>{if(cfg.mode!=='supabase')return oldRowClick(e);const id=e.target.dataset.retry;if(id){const r=records.find(r=>r.id===id);add([{nome:r.nome,cpf:r.cpf,telefone:r.telefone}])}};
if(cfg.mode!=='demo'&&cfg.mode!=='supabase'){cfg={mode:'demo',url:''};localStorage.setItem('config-v1',JSON.stringify(cfg))}$('#mode').value=cfg.mode;if(cfg.mode==='supabase')records=[];render();loadCloud();setInterval(loadCloud,8000);
